const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Sakurajima volcano location
  const volcano = ee.Geometry.Point([130.66, 31.58]);

  // Define directional regions (30km from volcano)
  const eastRegion = ee.Geometry.Rectangle([130.66, 31.48, 131.16, 31.68]);
  const southRegion = ee.Geometry.Rectangle([130.56, 31.08, 130.76, 31.58]);

  // 2. Time periods after eruption (May 21, 2015)
  const t1Start = '2015-05-21';
  const t1End = '2015-05-22';   // First day
  const t2Start = '2015-05-22';
  const t2End = '2015-05-24';   // Second-third day

  // 3. Get Terra MODIS Aerosol data (available from 2000)
  const aod1 = ee.ImageCollection('MODIS/006/MOD08_D3')
    .filterDate(t1Start, t1End)
    .select('Aerosol_Optical_Depth_Land_Mean');

  const aod2 = ee.ImageCollection('MODIS/006/MOD08_D3')
    .filterDate(t2Start, t2End)
    .select('Aerosol_Optical_Depth_Land_Mean');

  console.log('T1 Images:', aod1.size().getInfo());
  console.log('T2 Images:', aod2.size().getInfo());

  if (aod1.size().getInfo() === 0 || aod2.size().getInfo() === 0) {
    // Try Aqua MODIS as backup
    const aod1_aqua = ee.ImageCollection('MODIS/006/MYD08_D3')
      .filterDate(t1Start, t1End)
      .select('Aerosol_Optical_Depth_Land_Mean');

    const aod2_aqua = ee.ImageCollection('MODIS/006/MYD08_D3')
      .filterDate(t2Start, t2End)
      .select('Aerosol_Optical_Depth_Land_Mean');

    console.log('Aqua T1 Images:', aod1_aqua.size().getInfo());
    console.log('Aqua T2 Images:', aod2_aqua.size().getInfo());

    if (aod1_aqua.size().getInfo() === 0 || aod2_aqua.size().getInfo() === 0) {
      console.log('No aerosol data available for eruption period');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 4. Calculate mean AOD for each region and time
  const img1 = aod1.mean();
  const img2 = aod2.mean();

  const east_t1_stats = img1.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: eastRegion,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const south_t1_stats = img1.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: southRegion,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const east_t2_stats = img2.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: eastRegion,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const south_t2_stats = img2.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: southRegion,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const east_t1 = east_t1_stats['Aerosol_Optical_Depth_Land_Mean_mean'];
  const south_t1 = south_t1_stats['Aerosol_Optical_Depth_Land_Mean_mean'];
  const east_t2 = east_t2_stats['Aerosol_Optical_Depth_Land_Mean_mean'];
  const south_t2 = south_t2_stats['Aerosol_Optical_Depth_Land_Mean_mean'];

  const count_e1 = east_t1_stats['Aerosol_Optical_Depth_Land_Mean_count'];
  const count_s1 = south_t1_stats['Aerosol_Optical_Depth_Land_Mean_count'];
  const count_e2 = east_t2_stats['Aerosol_Optical_Depth_Land_Mean_count'];
  const count_s2 = south_t2_stats['Aerosol_Optical_Depth_Land_Mean_count'];

  console.log('East T1 (May 21-22): AOD=' + (east_t1 || 'null') + ', Pixels=' + count_e1);
  console.log('South T1 (May 21-22): AOD=' + (south_t1 || 'null') + ', Pixels=' + count_s1);
  console.log('East T2 (May 22-24): AOD=' + (east_t2 || 'null') + ', Pixels=' + count_e2);
  console.log('South T2 (May 22-24): AOD=' + (south_t2 || 'null') + ', Pixels=' + count_s2);

  // 5. Validation
  if (!count_e1 || !count_s1 || !count_e2 || !count_s2) {
    console.log('No valid pixels in one or more regions');
    console.log('<answer>C2</answer>');
    return;
  }

  if (east_t1 === null || south_t1 === null || east_t2 === null || south_t2 === null) {
    console.log('Calculation failed - null values');
    console.log('<answer>C3</answer>');
    return;
  }

  // 6. Determine direction pattern
  const first_east = east_t1 > south_t1;
  const then_south = south_t2 > east_t2;

  console.log('First East (T1):', first_east, '(E=' + east_t1.toFixed(4) + ' vs S=' + south_t1.toFixed(4) + ')');
  console.log('Then South (T2):', then_south, '(S=' + south_t2.toFixed(4) + ' vs E=' + east_t2.toFixed(4) + ')');

  if (first_east && then_south) {
    console.log('Pattern: First East, Then South');
    console.log('<answer>A</answer>');
  } else {
    console.log('Pattern does not match "first east then south"');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
